compliant:
import { Context, Effect, Layer } from "effect"

const make = Effect.sync(() => {
  const pending = new Set<string>()

  return {
    enqueue: (assetId: string) =>
      Effect.sync(() => {
        pending.add(assetId)
      }),
    takeBatch: Effect.sync((): ReadonlyArray<string> => {
      const batch = Array.from(pending)
      pending.clear()
      return batch
    }),
    size: Effect.sync(() => pending.size)
  }
})

export class ThumbnailQueue extends Context.Service<ThumbnailQueue>()(
  "media/ThumbnailQueue",
  { make }
) {
  static readonly layer = this.make.pipe(Layer.effect(this))
}

export const scheduleThumbnails = (assetIds: ReadonlyArray<string>) =>
  Effect.gen(function*() {
    const queue = yield* ThumbnailQueue

    for (const assetId of assetIds) {
      yield* queue.enqueue(assetId)
    }

    return yield* queue.size
  })
